BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT extensions.plan(15);
INSERT INTO auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data) VALUES
('f9000000-0000-4000-8000-000000000001','authenticated','authenticated','discussion-admin@local.test','{}','{}'),
('f9000000-0000-4000-8000-000000000002','authenticated','authenticated','discussion-outsider@local.test','{}','{}');
INSERT INTO public.organizations(id,name,username,type,join_code) VALUES('f9100000-0000-4000-8000-000000000001','Discussion fixtures','discussion-fixtures','school','739991');
INSERT INTO public.organization_members(organization_id,user_id,role,status) VALUES('f9100000-0000-4000-8000-000000000001','f9000000-0000-4000-8000-000000000001','admin','active');
INSERT INTO plugin_data.csf_terms(id,organization_id,code,label,school_year,semester) VALUES('f9200000-0000-4000-8000-000000000001','f9100000-0000-4000-8000-000000000001','F30','Fall 2030','2030-2031','fall');
INSERT INTO plugin_data.csf_sheet_sync_destinations(id,organization_id,spreadsheet_file_id,sheet_id,kind,term_id,is_test,configured_by,managed_headers) VALUES('f9400000-0000-4000-8000-000000000001','f9100000-0000-4000-8000-000000000001','fictional-discussion-copy',0,'applications','f9200000-0000-4000-8000-000000000001',true,'f9000000-0000-4000-8000-000000000001','["Record ID","Comments","Source version"]');
INSERT INTO plugin_data.csf_sheet_sync_bindings(organization_id,destination_id,record_kind,record_id,logical_key,sheet_id) VALUES('f9100000-0000-4000-8000-000000000001','f9400000-0000-4000-8000-000000000001','application','f9600000-0000-4000-8000-000000000001','fixture',0);
INSERT INTO plugin_data.csf_cohorts(id,organization_id,graduation_year,label) VALUES('f9500000-0000-4000-8000-000000000001','f9100000-0000-4000-8000-000000000001',2033,'Class of 2033');
INSERT INTO plugin_data.csf_profiles(id,organization_id,first_name,last_name,normalized_first_name,normalized_last_name) VALUES('f9300000-0000-4000-8000-000000000001','f9100000-0000-4000-8000-000000000001','Fictional','Student','fictional','student');
INSERT INTO plugin_data.csf_term_applications(id,organization_id,profile_id,cohort_id,term_id,source,status) VALUES('f9600000-0000-4000-8000-000000000001','f9100000-0000-4000-8000-000000000001','f9300000-0000-4000-8000-000000000001','f9500000-0000-4000-8000-000000000001','f9200000-0000-4000-8000-000000000001','manual','submitted');
SELECT plugin_data.csf_set_sheet_sync_destination_state('f9100000-0000-4000-8000-000000000001','f9000000-0000-4000-8000-000000000001','f9400000-0000-4000-8000-000000000001',true,true,'available');
UPDATE plugin_data.csf_sheet_sync_destinations SET discussion_transport='column' WHERE organization_id='f9100000-0000-4000-8000-000000000001';
CREATE TEMP TABLE obs_lease AS SELECT plugin_data.csf_claim_sheet_sync_destination('f9100000-0000-4000-8000-000000000001','f9400000-0000-4000-8000-000000000001',true) v;
UPDATE plugin_data.csf_sheet_sync_bindings SET last_export_version=md5(plugin_data.csf_sheet_sync_destination_snapshot(organization_id,destination_id,record_kind,record_id)::text),last_export_comments='Original' WHERE destination_id='f9400000-0000-4000-8000-000000000001';
CREATE FUNCTION pg_temp.obs_request(payload jsonb) RETURNS jsonb LANGUAGE sql AS $$ SELECT plugin_data.csf_record_sheet_sync_change('f9100000-0000-4000-8000-000000000001','f9400000-0000-4000-8000-000000000001','application','f9600000-0000-4000-8000-000000000001',(SELECT last_export_version FROM plugin_data.csf_sheet_sync_bindings WHERE destination_id='f9400000-0000-4000-8000-000000000001'),md5(payload::text),payload,(SELECT (v->>'poll_lease_token')::uuid FROM obs_lease)) $$;
CREATE FUNCTION pg_temp.obs_complete(valid boolean) RETURNS jsonb LANGUAGE sql AS $$ SELECT plugin_data.csf_complete_sheet_sync_observation('f9100000-0000-4000-8000-000000000001','f9400000-0000-4000-8000-000000000001',(SELECT (v->>'poll_lease_token')::uuid FROM obs_lease),valid) $$;
CREATE FUNCTION pg_temp.obs_review(id uuid) RETURNS jsonb LANGUAGE sql AS $$ SELECT plugin_data.csf_review_sheet_sync_change('f9100000-0000-4000-8000-000000000001','f9000000-0000-4000-8000-000000000001',id,true,'Reviewed complete observation') $$;
CREATE TEMP TABLE obs_changes(k text,v jsonb);
CREATE FUNCTION pg_temp.obs_toggle(enabled boolean) RETURNS jsonb LANGUAGE sql AS $$ SELECT plugin_data.csf_set_sheet_sync_destination_state('f9100000-0000-4000-8000-000000000001','f9000000-0000-4000-8000-000000000001','f9400000-0000-4000-8000-000000000001',enabled,true,'available') $$;
INSERT INTO obs_changes VALUES('original',pg_temp.obs_request('{"action":"approved"}'));
SELECT pg_temp.obs_complete(true);
SELECT plugin_data.csf_release_sheet_sync_destination('f9100000-0000-4000-8000-000000000001','f9400000-0000-4000-8000-000000000001',(SELECT (v->>'poll_lease_token')::uuid FROM obs_lease));
SELECT extensions.is(pg_temp.obs_toggle(true)->>'observation_state','valid','same enabled state preserves completed observation');
SELECT extensions.is((SELECT status FROM plugin_data.csf_sheet_sync_changes WHERE id=(SELECT (v->>'id')::uuid FROM obs_changes WHERE k='original')),'pending','same-state retry does not withdraw reviewed input');
SELECT extensions.is(pg_temp.obs_toggle(false)->>'observation_state','checking','disabling invalidates the previous observation');
SELECT extensions.is((SELECT status FROM plugin_data.csf_sheet_sync_changes WHERE id=(SELECT (v->>'id')::uuid FROM obs_changes WHERE k='original')),'stale','disabling retires pending proposals');
SELECT extensions.is((SELECT last_seen_request FROM plugin_data.csf_sheet_sync_bindings WHERE destination_id='f9400000-0000-4000-8000-000000000001'),'{}'::jsonb,'disabling resets withdrawn request baseline');
SELECT extensions.is(pg_temp.obs_review((SELECT (v->>'id')::uuid FROM obs_changes WHERE k='original'))->>'status','stale','old proposal cannot be accepted while disabled');
UPDATE plugin_data.csf_sheet_sync_changes SET status='pending' WHERE id=(SELECT (v->>'id')::uuid FROM obs_changes WHERE k='original');
UPDATE plugin_data.csf_sheet_sync_destinations SET observation_state='valid' WHERE id='f9400000-0000-4000-8000-000000000001';
SELECT extensions.throws_ok($$SELECT pg_temp.obs_review((SELECT (v->>'id')::uuid FROM obs_changes WHERE k='original'))$$,'P0001','Complete a valid Sheet observation before accepting this change.','disabled destination refuses acceptance even with a legacy valid state');
SELECT extensions.is(pg_temp.obs_toggle(true)->>'observation_state','checking','re-enabling requires a new observation');
SELECT extensions.is((SELECT status FROM plugin_data.csf_sheet_sync_changes WHERE id=(SELECT (v->>'id')::uuid FROM obs_changes WHERE k='original')),'stale','re-enabling also retires any pending legacy proposal');
UPDATE obs_lease SET v=plugin_data.csf_claim_sheet_sync_destination('f9100000-0000-4000-8000-000000000001','f9400000-0000-4000-8000-000000000001',true);
INSERT INTO obs_changes VALUES('repaired',pg_temp.obs_request('{"action":"approved"}'));
SELECT extensions.isnt((SELECT v->>'id' FROM obs_changes WHERE k='original'),(SELECT v->>'id' FROM obs_changes WHERE k='repaired'),'same input after re-enable gets a fresh observation identity');
SELECT extensions.throws_ok($$SELECT pg_temp.obs_review((SELECT (v->>'id')::uuid FROM obs_changes WHERE k='repaired'))$$,'P0001','Complete a valid Sheet observation before accepting this change.','re-enabled proposal remains held until observation completes');
SELECT pg_temp.obs_complete(true);
SELECT plugin_data.csf_release_sheet_sync_destination('f9100000-0000-4000-8000-000000000001','f9400000-0000-4000-8000-000000000001',(SELECT (v->>'poll_lease_token')::uuid FROM obs_lease));
SELECT extensions.is(pg_temp.obs_review((SELECT (v->>'id')::uuid FROM obs_changes WHERE k='repaired'))->>'status','accepted','fresh completed released observation permits staff review');
SELECT pg_temp.obs_toggle(false);
SELECT extensions.is((SELECT status FROM plugin_data.csf_sheet_sync_changes WHERE id=(SELECT (v->>'id')::uuid FROM obs_changes WHERE k='repaired')),'accepted','disabling preserves completed staff history');
SELECT extensions.is((SELECT status FROM plugin_data.csf_sheet_sync_changes WHERE id=(SELECT (v->>'id')::uuid FROM obs_changes WHERE k='original')),'stale','original withdrawn history remains preserved');
SELECT extensions.ok(NOT has_function_privilege('authenticated','plugin_data.csf_set_sheet_sync_destination_state(uuid,uuid,uuid,boolean,boolean,text)','EXECUTE'),'state changes remain service-only');
SELECT * FROM extensions.finish();
ROLLBACK;
